<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';
import {Play,Pause,RotateCcw,StepForward,Activity,Tractor,Map,ClipboardList,Terminal,AlertTriangle,Route,Download,Plus,ChevronDown,CheckCircle2,Fuel,Clock3,Info,ShieldCheck,Zap} from 'lucide-vue-next';
import scenario from './data/scenario.json';
import {agentHealth, explainReplan, askWhy} from './agentApi.js';
import {whyFacts} from './engine/agents.js';
import FarmMap from './components/FarmMap.vue';
import AlertToasts from './components/AlertToasts.vue';
import {createState,tick,breakdown,repair,blockCell,changePriority,addJob,runToEnd,exportLog,route,refuel,updateTractor,updateJob} from './engine/core.js';
const config=ref(JSON.parse(JSON.stringify(scenario)));const sim=ref(createState(config.value));const running=ref(false),speed=ref(0.5),selected=ref({kind:'tractor',id:'T1'}),tab=ref('inspector'),consoleFilter=ref('all'),blockMode=ref(false),showJob=ref(false),showTractor=ref(false),showAddTractor=ref(false),showEditJob=ref(false),baseline=ref(null),newJob=ref({fieldId:'F1',type:'spray',priority:2,deadline:90,duration:8});
let timer=null;const tractors=computed(()=>sim.value.tractors),jobs=computed(()=>sim.value.jobs),fields=computed(()=>sim.value.fields),completed=computed(()=>jobs.value.filter(j=>j.status==='done').length),progress=computed(()=>Math.round(completed.value/jobs.value.length*100)),selectedTractor=computed(()=>selected.value.kind==='tractor'?tractors.value.find(t=>t.id===selected.value.id):null),selectedField=computed(()=>selected.value.kind==='field'?fields.value.find(f=>f.id===selected.value.id):null),selectedJob=computed(()=>selected.value.kind==='job'?jobs.value.find(j=>j.id===selected.value.id):null),filteredLogs=computed(()=>sim.value.logs.filter(l=>consoleFilter.value==='all'||l.type===consoleFilter.value).slice(0,80));
const addTractorDraft=ref({name:'Atlas 04',x:8,y:10,speed:1.5,fuel:100,implements:['sprayer']});const tractorDraft=ref({speed:1,fuel:90,implements:['sprayer']});const jobDraft=ref({duration:8,deadline:90,priority:2});const fileInput=ref(null);
// ── AI Farm Orchestrator panel ──
// Decisions come from the deterministic agents in engine/agents.js. The Explainer Agent (Ollama, via the
// FastAPI backend) only rewrites their facts into plain English. Template text shows first; LLM text replaces it on arrival.
const aiStatus=ref('Explainer not checked'), aiOnline=ref(false);
async function checkAI(){try{const h=await agentHealth();aiOnline.value=h.ollama==='online';aiStatus.value=h.ollama==='online'?`Explainer LLM online · ${h.model}`:h.ollama==='mock'?'Backend online · template mode':'Backend online · Ollama offline (templates)';if(aiOnline.value)explainNew();}catch(e){aiOnline.value=false;aiStatus.value='Explainer offline · using template explanations';}}
// Only send meaningful replans to the LLM (first plan, handoffs, vetoes, refuels, at-risk jobs) so requests don't pile up.
const worthExplaining=e=>e.version===1||e.diff.moved.length||e.diff.vetoes.length||e.diff.refuels.length||e.diff.at_risk.length;
function explainNew(){if(!aiOnline.value)return;for(const e of sim.value.explanations){if(e.requested||!worthExplaining(e))continue;e.requested=true;e.pending=true;const target=e;explainReplan(JSON.parse(JSON.stringify(e.diff)),e.template).then(r=>{if(r?.text){target.text=r.text;target.source=r.source;target.model=r.model;}}).catch(()=>{}).finally(()=>{target.pending=false;});}}
watch(()=>sim.value.explanations.length,explainNew);
const latestExplanation=computed(()=>sim.value.explanations.at(-1)||null);
const recentExplanations=computed(()=>sim.value.explanations.slice(-4).reverse());
const AGENTS=[{id:'Orchestrator',role:'Event loop · replans on triggers'},{id:'Fleet',role:'Regret auction · proposes plans'},{id:'Navigation',role:'Routes · detours · depot reserve'},{id:'Safety',role:'APPROVE / VETO · invariants'},{id:'Agronomy',role:'Wind & wet-field rules'},{id:'Explainer',role:'LLM · plain language only'}];
const agentCards=computed(()=>{const msgs=sim.value.messages;return AGENTS.map(a=>{const mine=a.id==='Agronomy'?msgs.filter(m=>m.kind==='VETO'&&m.detail.startsWith('Agronomy')):msgs.filter(m=>m.from===a.id);const last=mine.at(-1);let note=last?`[${last.kind}] ${last.detail}`:'No messages yet';if(a.id==='Agronomy'){const g=sim.value.agronomy||{};const rules=[...(g.wind||[]).map(w=>`wind ${w.kmh} km/h t=${w.from}–${w.to}`),...(g.wetFields||[]).map(w=>`${w.fieldId} wet until t=${w.until}`)];note=(rules.length?'Rules: '+rules.join(' · '):'No rules')+(last?` — last veto t=${last.time}`:'');}return {...a,count:mine.length,note};});});
const agentFeed=computed(()=>sim.value.messages.slice(-40).reverse());
// "Why?" questions on a job. Facts (bids, Safety vetoes, forced what-if) are computed in code, then phrased by the LLM.
const whyQuestion=ref(''), whyAnswer=ref(null), whyBusy=ref(false);
async function askWhyJob(){const j=selectedJob.value;if(!j)return;const q=whyQuestion.value.trim()||`Why is ${j.id} assigned this way?`;const r=whyFacts(sim.value,j.id,q);if(!r)return;whyAnswer.value={job:j.id,question:q,text:r.template,source:'template',facts:r.facts};if(!aiOnline.value)return;whyBusy.value=true;try{const a=await askWhy(q,JSON.parse(JSON.stringify(r.facts)),r.template);if(whyAnswer.value?.job===j.id&&whyAnswer.value.question===q&&a?.text)whyAnswer.value={...whyAnswer.value,text:a.text,source:a.source,model:a.model};}catch(e){}finally{whyBusy.value=false;}}
const fieldColor={wheat:'#8b8651',corn:'#557e4b',grass:'#4c806a',soy:'#71865d',orchard:'#657c59'};
const fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
function start(){running.value=true}function pause(){running.value=false}function reset(){running.value=false;sim.value=createState(config.value,sim.value.mode);selected.value={kind:'tractor',id:'T1'};baseline.value=null}function step(){if(sim.value.time>=sim.value.horizon){running.value=false;return;}tick(sim.value)}
// Fractional speeds (0.5×) accumulate: one sim minute every 1/speed intervals.
let stepCredit=0;function loop(){if(!running.value)return;stepCredit+=speed.value;while(stepCredit>=1-1e-9){stepCredit-=1;step();}}// Tractors glide between ticks: each tick's move is animated over exactly one tick interval (see .tractor-glyph).
const TICK_MS=550;
onMounted(()=>{timer=setInterval(loop,TICK_MS);checkAI();});onUnmounted(()=>clearInterval(timer));
function select(kind,id){selected.value={kind,id};tab.value='inspector'}
function clickCell(x,y){if(blockMode.value){blockCell(sim.value,x,y);return;}const t=tractors.value.find(t=>t.x===x&&t.y===y);if(t){select('tractor',t.id);return;}const f=fields.value.find(f=>x>=f.x&&x<f.x+f.w&&y>=f.y&&y<f.y+f.h);if(f)select('field',f.id)}
function doBreak(){if(selectedTractor.value)breakdown(sim.value,selectedTractor.value.id)}
function compare(){const events=config.value.events||[];const smart=runToEnd(config.value,'smart',events),basic=runToEnd(config.value,'baseline',events);baseline.value={smart:smart.metrics,basic:basic.metrics,smartStats:smart.agentStats,events};tab.value='compare'}
const r1=x=>Math.round(x*10)/10;
function download(content,name){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function submitJob(){if(addJob(sim.value,{...newJob.value,priority:Number(newJob.value.priority),duration:Number(newJob.value.duration),deadline:Number(newJob.value.deadline)})){showJob.value=false;syncConfig();}else alert('Please provide a valid future deadline and positive duration.');}
function switchMode(mode){if(sim.value.mode===mode)return;running.value=false;sim.value=createState(scenario,mode);baseline.value=null}
function submitTractor(){const d=addTractorDraft.value;if(!d.name.trim()||!Number.isFinite(Number(d.speed))||Number(d.speed)<=0||!Number.isFinite(Number(d.fuel))||Number(d.fuel)<0||Number(d.fuel)>100||!d.implements.length){alert('Enter a valid tractor name, speed, fuel, and implement.');return;}const id=`T${Math.max(0,...sim.value.tractors.map(t=>Number(t.id.slice(1))||0))+1}`;const tractor={id,name:d.name,x:Number(d.x),y:Number(d.y),fuel:Number(d.fuel),capacity:100,speed:Number(d.speed),travelBurn:.75,workBurn:.85,implements:[...d.implements],capabilities:d.implements.map(i=>({harvester:'harvest',sprayer:'spray',mower:'mow'}[i])),color:'#8dd7e2',status:'idle',jobId:null,path:[],travel:0,idle:0,work:0,reason:'Newly added tractor'};sim.value.tractors.push(tractor);sim.value.logs.unshift({id:sim.value.nextLog++,time:sim.value.time,type:'system',message:`Operator added ${d.name}.`});syncConfig();showAddTractor.value=false;select('tractor',id);}
function openTractorEdit(){if(!selectedTractor.value)return;tractorDraft.value={speed:selectedTractor.value.speed,fuel:selectedTractor.value.fuel,implements:[...selectedTractor.value.implements]};showTractor.value=true;}
function saveTractor(){if(updateTractor(sim.value,selectedTractor.value.id,{...tractorDraft.value,speed:Number(tractorDraft.value.speed),fuel:Number(tractorDraft.value.fuel)})){showTractor.value=false;syncConfig();}else alert('Tractor must be idle. Check speed, fuel and implements.');}
function openJobEdit(){if(!selectedJob.value)return;jobDraft.value={duration:selectedJob.value.duration,deadline:selectedJob.value.deadline,priority:selectedJob.value.priority};showEditJob.value=true;}
function saveJob(){if(updateJob(sim.value,selectedJob.value.id,{...jobDraft.value,duration:Number(jobDraft.value.duration),deadline:Number(jobDraft.value.deadline),priority:Number(jobDraft.value.priority)})){showEditJob.value=false;syncConfig();}else alert('Only pending jobs can be edited. Check deadline and duration.');}
function syncConfig(){config.value.tractors=sim.value.tractors.map(t=>({id:t.id,name:t.name,x:t.x,y:t.y,fuel:t.fuel,capacity:t.capacity,speed:t.speed,travelBurn:t.travelBurn,workBurn:t.workBurn,implements:[...t.implements],capabilities:[...t.capabilities],color:t.color}));config.value.jobs=sim.value.jobs.map(j=>({id:j.id,fieldId:j.fieldId,type:j.type,priority:j.priority,deadline:j.deadline,duration:j.duration}));}
function loadScenario(ev){const f=ev.target.files?.[0];if(!f)return;f.text().then(raw=>{try{const data=JSON.parse(raw);if(!Array.isArray(data.tractors)||!Array.isArray(data.jobs)||!Array.isArray(data.fields)||!Number.isFinite(data.horizon)||!data.station)throw Error('Invalid scenario structure');config.value=data;reset();}catch(err){alert('Could not load scenario: '+err.message);}ev.target.value='';});}
const statusLabel={idle:'Available',traveling:'In transit',working:'Working',refueling:'Refueling',broken:'Offline',done:'Done'};
</script>
<template>
<div class="app-shell">
  <AlertToasts :sim="sim" @select="select"/>
  <header class="topbar"><div class="brand"><div class="brand-mark"><Tractor :size="21"/></div><div><strong>FIELD<span>OPS</span></strong><small>FLEET SIMULATION STUDIO</small></div></div><div class="project-name"><span class="online-dot"></span> Willow Creek Cooperative <span class="project-tag">SCENARIO 01</span></div><div class="toolbar"><span class="time-label"><Clock3 :size="15"/> {{fmt(sim.time)}} <small>SIM TIME</small></span><div class="divider"></div><button class="icon-btn" title="Reset simulation" @click="reset"><RotateCcw :size="17"/></button><button class="icon-btn" title="Advance one minute" @click="step"><StepForward :size="18"/></button><button class="play-btn" @click="running?pause():start()"><Pause v-if="running" :size="16"/><Play v-else :size="16"/> {{running?'Pause':'Run simulation'}}</button><select v-model.number="speed" class="speed" aria-label="Simulation speed"><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option><option :value="8">8×</option></select></div></header>
  <div class="workspace">
    <div class="left-stack">
    <aside class="sidebar inspector-side"><div class="right-tabs"><button :class="{active:tab==='inspector'}" @click="tab='inspector'">INSPECTOR</button><button :class="{active:tab==='compare'}" @click="tab='compare'">ANALYTICS</button></div><div v-if="tab==='inspector'" class="inspector"><template v-if="selectedTractor"><div class="inspector-hero"><div class="hero-icon" :style="{color:selectedTractor.color}"><Tractor :size="29"/></div><div><span class="eyebrow">FLEET ASSET / {{selectedTractor.id}}</span><h2>{{selectedTractor.name}}</h2><span class="state-pill" :class="selectedTractor.status">{{statusLabel[selectedTractor.status]}}</span></div></div><div class="detail-section"><h3>TELEMETRY</h3><div class="detail-row"><span>Fuel remaining</span><strong>{{Math.round(selectedTractor.fuel)}}%</strong></div><div class="fuel-bar"><div :style="{width:selectedTractor.fuel+'%',background:selectedTractor.fuel<25?'#e78c79':'#66d6b0'}"></div></div><div class="detail-row"><span>Coordinates</span><strong>{{r1(selectedTractor.x)}}, {{r1(selectedTractor.y)}}</strong></div><div class="detail-row"><span>Travel / Idle</span><strong>{{r1(selectedTractor.travel)}} / {{selectedTractor.idle}} min</strong></div><div class="detail-row"><span>Capabilities</span><strong>{{selectedTractor.capabilities.join(', ')}}</strong></div></div><div class="detail-section"><h3>CURRENT ASSIGNMENT</h3><div class="assignment-card"><span>{{selectedTractor.jobId||'No active job'}}</span><p>{{selectedTractor.reason}}</p></div></div><div class="detail-section"><button class="small-btn full" @click="openTractorEdit">Edit tractor</button><button class="small-btn full" style="margin-top:8px" :disabled="selectedTractor.status!=='idle'" @click="refuel(sim,selectedTractor.id)">Refuel idle tractor</button></div><div class="detail-section"><h3>SIMULATION EVENTS</h3><button v-if="selectedTractor.status!=='broken'" class="danger-btn" @click="doBreak"><AlertTriangle :size="15"/> Trigger breakdown</button><button v-else class="small-btn full" @click="repair(sim,selectedTractor.id)"><ShieldCheck :size="15"/> Repair tractor</button></div></template><template v-else-if="selectedField"><div class="inspector-hero"><div class="hero-icon">🌾</div><div><span class="eyebrow">FIELD / {{selectedField.id}}</span><h2>{{selectedField.name}}</h2><span class="state-pill">{{selectedField.crop}}</span></div></div><div class="detail-section"><h3>FIELD PROPERTIES</h3><div class="detail-row"><span>Coordinates</span><strong>{{selectedField.x}}, {{selectedField.y}}</strong></div><div class="detail-row"><span>Size</span><strong>{{selectedField.w}} × {{selectedField.h}} cells</strong></div></div><div class="detail-section"><h3>ASSOCIATED JOBS</h3><button v-for="j in jobs.filter(j=>j.fieldId===selectedField.id)" :key="j.id" class="job-item" @click="select('job',j.id)">{{j.id}} · {{j.type}} <span>{{Math.round(j.progress*100)}}%</span></button></div></template><template v-else-if="selectedJob"><div class="inspector-hero"><div class="hero-icon"><ClipboardList :size="26"/></div><div><span class="eyebrow">WORK ORDER / {{selectedJob.id}}</span><h2>{{selectedJob.type.toUpperCase()}}</h2><span class="state-pill">{{selectedJob.status}}</span></div></div><div class="detail-section"><button class="small-btn full" @click="openJobEdit" :disabled="selectedJob.status!=='pending'">Edit pending job</button><p class="note">{{selectedJob.reason}}</p></div><div class="detail-section"><h3>JOB DETAILS</h3><div class="detail-row"><span>Field</span><strong>{{selectedJob.fieldId}}</strong></div><div class="detail-row"><span>Assigned tractor</span><strong>{{selectedJob.tractorId||'Unassigned'}}</strong></div><div class="detail-row"><span>Deadline</span><strong>t={{selectedJob.deadline}}</strong></div><div class="detail-row"><span>Duration</span><strong>{{selectedJob.duration}} min</strong></div><div class="detail-row"><span>Progress</span><strong>{{Math.round(selectedJob.progress*100)}}%</strong></div><div class="progress-track"><div :style="{width:selectedJob.progress*100+'%'}"></div></div><div class="detail-row"><span>Priority</span><select :value="selectedJob.priority" :disabled="selectedJob.status==='done'" @change="changePriority(sim,selectedJob.id,Number($event.target.value))"><option :value="1">Low</option><option :value="2">Medium</option><option :value="3">High</option></select></div></div><div class="detail-section"><h3>ASK WHY</h3><form class="why-form" @submit.prevent="askWhyJob"><input v-model="whyQuestion" :placeholder="`Why ${selectedJob.tractorId||'this'}? / why not T3?`"/><button class="small-btn" type="submit" :disabled="whyBusy">{{whyBusy?'…':'Why?'}}</button></form><div v-if="whyAnswer&&whyAnswer.job===selectedJob.id" class="assignment-card why-answer"><span>{{whyAnswer.question}} <em class="source-badge" :class="whyAnswer.source">{{whyBusy?'LLM writing…':whyAnswer.source==='llm'?'LLM':'template'}}</em></span><p>{{whyAnswer.text}}</p><details><summary>Facts used</summary><pre>{{JSON.stringify(whyAnswer.facts,null,1)}}</pre></details></div></div></template></div><div v-else class="inspector analytics"><div class="eyebrow">PERFORMANCE BENCHMARK</div><h2>Dispatcher comparison</h2><p>Run both algorithms against the same scenario, including the scenario’s scripted events. Results cover the configured simulation horizon.</p><div class="mode-switch"><button :class="{active:sim.mode==='smart'}" @click="switchMode('smart')">Smart</button><button :class="{active:sim.mode==='baseline'}" @click="switchMode('baseline')">FIFO baseline</button></div><button class="play-btn full" @click="compare"><Activity :size="15"/> Run fair comparison</button><template v-if="baseline"><table><thead><tr><th>METRIC</th><th>FIFO</th><th>SMART</th></tr></thead><tbody><tr><td>Completed</td><td>{{baseline.basic.completed}}</td><td>{{baseline.smart.completed}}</td></tr><tr><td>Travel min</td><td>{{r1(baseline.basic.travel)}}</td><td>{{r1(baseline.smart.travel)}}</td></tr><tr><td>Travel / job</td><td>{{baseline.basic.completed?r1(baseline.basic.travel/baseline.basic.completed):'–'}}</td><td>{{baseline.smart.completed?r1(baseline.smart.travel/baseline.smart.completed):'–'}}</td></tr><tr><td>Idle min</td><td>{{baseline.basic.idle}}</td><td>{{baseline.smart.idle}}</td></tr><tr><td>Missed deadlines</td><td>{{baseline.basic.missed}}</td><td>{{baseline.smart.missed}}</td></tr><tr><td>Agronomy breaches</td><td>{{baseline.basic.agronomyBreaches}}</td><td>{{baseline.smart.agronomyBreaches}}</td></tr><tr><td>Violations</td><td>{{baseline.basic.violations}}</td><td>{{baseline.smart.violations}}</td></tr><tr><td>Replans / vetoes / refuels</td><td>–</td><td>{{baseline.smartStats.replans}} / {{baseline.smartStats.vetoes}} / {{baseline.smartStats.refuels}}</td></tr></tbody></table><p class="note">Benchmark uses identical initial conditions and event timing. This is a deterministic illustrative farm model, not real tractor telemetry.</p></template></div></aside>
    <aside class="sidebar left"><div class="panel-heading"><span><Map :size="15"/> SCENE EXPLORER</span><button class="small-btn" title="Add tractor" @click="showAddTractor=true">+ Tractor</button><span class="count">{{tractors.length+fields.length+jobs.length}}</span></div><div class="scene-scroll"><div class="section-title"><ChevronDown :size="13"/> TRACTOR FLEET <span>{{tractors.length}}</span></div><button v-for="t in tractors" :key="t.id" class="tree-row" :class="{active:selected.kind==='tractor'&&selected.id===t.id}" @click="select('tractor',t.id)"><span class="tractor-icon" :style="{color:t.color}"><Tractor :size="16"/></span><span class="tractor-tree-name">{{t.name}}</span><span class="tractor-battery" :class="{low:t.fuel<=20,medium:t.fuel>20&&t.fuel<=45}" :title="`${t.name}: ${Math.round(t.fuel)}% fuel remaining`" :aria-label="`${Math.round(t.fuel)} percent fuel remaining`"><span class="battery-shell"><span class="battery-fill" :style="{width:`${Math.max(0,Math.min(100,t.fuel))}%`}"></span></span><span class="battery-percentage">{{Math.round(t.fuel)}}%</span></span><span class="status-dot" :class="t.status"></span></button><div class="section-title"><ChevronDown :size="13"/> AGRICULTURAL FIELDS <span>{{fields.length}}</span></div><button v-for="f in fields" :key="f.id" class="tree-row" :class="{active:selected.kind==='field'&&selected.id===f.id}" @click="select('field',f.id)"><span class="field-icon" :style="{background:fieldColor[f.crop]}"></span><span>{{f.name}}</span><small>{{f.id}}</small></button><div class="section-title"><ChevronDown :size="13"/> WORK QUEUE <span>{{jobs.length}}</span></div><button v-for="j in jobs" :key="j.id" class="tree-row" :class="{active:selected.kind==='job'&&selected.id===j.id}" @click="select('job',j.id)"><ClipboardList :size="15" class="muted"/><span>{{j.id}} · {{j.type}}</span><span class="mini-dot" :class="j.status"></span></button></div><div class="sidebar-bottom"><span class="online-dot"></span> ALL SYSTEMS MONITORED <span>v0.1.0</span></div></aside>
    </div>
    <main class="center"><div class="viewport-header"><div><span class="eyebrow">SIMULATION / WORLD VIEW</span><h1>Farm Overview <span class="live-badge"><span class="online-dot"></span> {{running?'LIVE':'READY'}}</span></h1></div><div class="viewport-actions"><button class="small-btn" @click="fileInput.click()">Load JSON</button><input ref="fileInput" type="file" accept=".json,application/json" hidden @change="loadScenario"/><button class="small-btn" :class="{selected:blockMode}" @click="blockMode=!blockMode"><Route :size="15"/> {{blockMode?'Click map to toggle':'Block route'}}</button><button class="small-btn" @click="showJob=true"><Plus :size="15"/> New job</button></div></div>
      <div class="viewport"><div class="map-head"><span><span class="tiny-square"></span> WILLOW CREEK / TOPOGRAPHIC GRID</span><span>{{sim.width}} × {{sim.height}} GRID · SIMULATED MINUTES</span></div><FarmMap :sim="sim" :selected="selected" :block-mode="blockMode" :tick-ms="TICK_MS/Math.min(1,speed)" :field-color="fieldColor" @select="select" @cell="clickCell"/><div class="map-footer"><span><span class="legend-dot" style="background:#66d6b0"></span> Active tractor</span><span><span class="legend-dot" style="background:#e7ba72"></span> Planned road route</span><span><span class="legend-dot" style="background:#6e5f45"></span> Farm lane / gate</span><span><span class="legend-dot" style="background:#d9c27a"></span> Worked swath · arrows = coverage plan</span><span><span class="legend-dot" style="background:#e57d70"></span> Blocked cell</span><span class="map-scale">SCHEMATIC · NOT TO SCALE</span></div></div>
      <div class="metrics"><div class="metric"><span>JOBS COMPLETED</span><strong>{{sim.metrics.completed}} <small>/ {{jobs.length}}</small></strong><div class="progress-track"><div :style="{width:progress+'%'}"></div></div></div><div class="metric"><span>TRAVEL TIME</span><strong>{{r1(sim.metrics.travel)}} <small>min</small></strong><small>Across all tractors</small></div><div class="metric"><span>IDLE TIME</span><strong>{{sim.metrics.idle}} <small>min</small></strong><small>Across all tractors</small></div><div class="metric"><span>CONSTRAINT ISSUES</span><strong :class="sim.metrics.violations?'danger':'good'">{{sim.metrics.violations}}</strong><small>{{sim.metrics.missed}} missed deadlines</small></div></div>
    </main>

  </div>
  <section class="ai-panel" aria-label="AI Farm Orchestrator">
    <div class="ai-heading"><strong>AI FARM ORCHESTRATOR</strong><span class="plan-chip" v-if="sim.mode==='smart'">PLAN v{{sim.planVersion}} · {{sim.agentStats.replans}} replans · {{sim.agentStats.vetoes}} vetoes · {{sim.agentStats.refuels}} refuels · avg {{sim.agentStats.replans?r1(sim.agentStats.latencyMs/sim.agentStats.replans):0}} ms</span><span class="plan-chip" v-else>FIFO BASELINE · agents off</span><span>{{aiStatus}}</span><button class="small-btn" @click="checkAI">Check Explainer</button></div>
    <div class="ai-controls"><small>The LLM talks to the farmer. Code makes the decisions it can prove: Fleet proposes → Safety approves or vetoes → Orchestrator commits → Explainer describes.</small></div>
    <div class="agent-grid"><div v-for="a in agentCards" :key="a.id" class="agent-card" :class="'agent-'+a.id.toLowerCase()"><div class="agent-card-head"><strong>{{a.id}}</strong><span>{{a.count}}</span></div><small>{{a.role}}</small><p>{{a.note}}</p></div></div>
    <div class="orchestrator-body">
      <div class="explain-box"><div class="explain-head"><strong>LATEST PLAN EXPLANATION</strong><span v-if="latestExplanation" class="source-badge" :class="latestExplanation.source">{{latestExplanation.pending?'LLM writing…':latestExplanation.source==='llm'?'LLM · '+latestExplanation.model:'template'}}</span></div><p v-if="latestExplanation"><b>[{{fmt(latestExplanation.time)}}] v{{latestExplanation.version}}</b> {{latestExplanation.text}}</p><p v-else class="muted">{{sim.mode==='smart'?'No plan yet.':'Switch to Smart mode in Analytics to enable the agents.'}}</p><details v-if="recentExplanations.length>1"><summary>Earlier explanations</summary><p v-for="e in recentExplanations.slice(1)" :key="e.id"><b>[{{fmt(e.time)}}] v{{e.version}}</b> {{e.text}}</p></details></div>
      <div class="agent-feed"><div class="explain-head"><strong>AGENT MESSAGES</strong><span>{{sim.messages.length}}</span></div><div v-for="m in agentFeed" :key="m.id" class="feed-row"><span class="log-time">[{{fmt(m.time)}}]</span><span class="feed-route">{{m.from}} → {{m.to}}</span><span class="kind-badge" :class="'kind-'+m.kind.toLowerCase()">{{m.kind}}</span><span class="feed-detail">{{m.jobId?m.jobId+': ':''}}{{m.detail}}</span></div><div v-if="!agentFeed.length" class="empty">No agent messages yet.</div></div>
    </div>
  </section>
  <section class="console"><div class="console-header"><span><Terminal :size="16"/> EVENT CONSOLE <small>{{sim.logs.length}} EVENTS</small></span><div><select v-model="consoleFilter" aria-label="Filter events"><option value="all">All events</option><option value="assignment">Assignments</option><option value="message">Agent messages</option><option value="decision">Decisions</option><option value="critical">Critical</option><option value="success">Completed</option><option value="warning">Warnings</option></select><button class="small-btn" @click="download(exportLog(sim),'fieldops-event-log.json')"><Download :size="14"/> Export log</button><button class="small-btn" @click="download(JSON.stringify(config.value,null,2),'fieldops-scenario.json')"><Download :size="14"/> Scenario</button></div></div><div class="console-body"><div v-for="l in filteredLogs" :key="l.id" class="log-row"><span class="log-time">[{{fmt(l.time)}}]</span><span class="log-type" :class="l.type">{{l.type.toUpperCase()}}</span><span>{{l.message}}</span></div><div v-if="!filteredLogs.length" class="empty">No events for this filter.</div></div></section>
  <div v-if="showAddTractor" class="modal-overlay" @click.self="showAddTractor=false"><form class="modal" @submit.prevent="submitTractor"><div class="modal-title"><h2>Add tractor</h2><button type="button" class="icon-btn" @click="showAddTractor=false">✕</button></div><label>Name<input v-model="addTractorDraft.name" required/></label><label>Start X<input type="number" min="0" :max="sim.width-1" v-model.number="addTractorDraft.x" required/></label><label>Start Y<input type="number" min="0" :max="sim.height-1" v-model.number="addTractorDraft.y" required/></label><label>Speed<input type="number" min="0.1" step="0.1" v-model.number="addTractorDraft.speed" required/></label><label>Fuel<input type="number" min="0" max="100" v-model.number="addTractorDraft.fuel" required/></label><label>Implements<select multiple v-model="addTractorDraft.implements"><option value="harvester">Harvester</option><option value="sprayer">Sprayer</option><option value="mower">Mower</option></select></label><button type="submit" class="play-btn">Add tractor</button></form></div>
  <div v-if="showTractor" class="modal-overlay" @click.self="showTractor=false"><form class="modal" @submit.prevent="saveTractor"><div class="modal-title"><h2>Edit tractor</h2><button type="button" class="icon-btn" @click="showTractor=false">✕</button></div><label>Speed (grid units / minute)<input type="number" step="0.1" min="0.1" v-model.number="tractorDraft.speed" required/></label><label>Fuel level<input type="number" min="0" :max="selectedTractor?.capacity||100" v-model.number="tractorDraft.fuel" required/></label><label>Implements (multi-select with Ctrl/Command)<select multiple v-model="tractorDraft.implements"><option value="harvester">Harvester</option><option value="sprayer">Sprayer</option><option value="mower">Mower</option></select></label><button class="play-btn" type="submit">Save tractor</button></form></div>
  <div v-if="showEditJob" class="modal-overlay" @click.self="showEditJob=false"><form class="modal" @submit.prevent="saveJob"><div class="modal-title"><h2>Edit pending job</h2><button type="button" class="icon-btn" @click="showEditJob=false">✕</button></div><label>Duration<input type="number" min="1" v-model.number="jobDraft.duration" required/></label><label>Deadline<input type="number" min="1" v-model.number="jobDraft.deadline" required/></label><label>Priority<select v-model.number="jobDraft.priority"><option :value="1">Low</option><option :value="2">Medium</option><option :value="3">High</option></select></label><button class="play-btn" type="submit">Save job</button></form></div>
  <div v-if="showJob" class="modal-overlay" @click.self="showJob=false"><form class="modal" @submit.prevent="submitJob"><div class="modal-title"><h2>Create work order</h2><button type="button" class="icon-btn" @click="showJob=false">✕</button></div><label>Field<select v-model="newJob.fieldId"><option v-for="f in fields" :key="f.id" :value="f.id">{{f.name}}</option></select></label><label>Job type<select v-model="newJob.type"><option value="spray">Spray</option><option value="harvest">Harvest</option><option value="mow">Mow</option></select></label><label>Priority<select v-model.number="newJob.priority"><option :value="1">Low</option><option :value="2">Medium</option><option :value="3">High</option></select></label><label>Duration (simulated minutes)<input v-model.number="newJob.duration" type="number" min="1" max="200" required/></label><label>Deadline (absolute simulation minute)<input v-model.number="newJob.deadline" type="number" :min="sim.time+1" max="500" required/></label><button type="submit" class="play-btn full">Add job to queue</button></form></div>
</div>
</template>
